fn min3(a: Int, b: Int, c: Int) -> Int {
  return a.min(b).min(c)
}

fn cell_value(prev: List[Int], cur: List[Int], ca: Str, cb: List[Str], j: Int) -> Int {
  let same = ca == cb.get_or(j - 1, "")
  let sub = match same {
    true => 0,
    false => 1,
  }
  let up = prev.get_or(j, 0) + 1
  let left = cur.last().unwrap_or(0) + 1
  let diag = prev.get_or(j - 1, 0) + sub
  return min3(a: up, b: left, c: diag)
}

fn next_row(prev: List[Int], ca: Str, cb: List[Str], i: Int) -> List[Int] {
  let start: List[Int] = [i]
  let cols = range(1, cb.len() + 1)
  return cols.fold(start, fn(cur, j) => cur.push(cell_value(prev: prev, cur: cur, ca: ca, cb: cb, j: j)))
}

pub fn edit(a: Str, b: Str) -> Int {
  let bs = b.chars()
  let as_chars = a.chars()
  let first_row = range(0, bs.len() + 1)
  let final_row = range(1, as_chars.len() + 1).fold(first_row, fn(row, i) => next_row(prev: row, ca: as_chars.get_or(i - 1, ""), cb: bs, i: i))
  return final_row.last().unwrap_or(0)
}
